const fs = require('fs');
const { chromium } = require('playwright');

(async () => {
  const htmlPath = '/app/output/viz.html';
  const outPath = '/app/output/result.png';

  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1500, height: 980, deviceScaleFactor: 2 } });
  await page.goto('file://' + htmlPath, { waitUntil: 'load' });

  // Wait for charts to draw
  await page.waitForTimeout(300);

  // Ensure light theme for editorial default
  await page.evaluate(() => {
    if (typeof applyTheme === 'function') applyTheme('light');
  });
  await page.waitForTimeout(200);

  await page.screenshot({ path: outPath, fullPage: true });
  await browser.close();

  const stat = fs.statSync(outPath);
  console.log('Wrote', outPath, stat.size, 'bytes');
})();
NODE

